import{_ as a,o as d,c as r,a2 as t}from"./chunks/framework.D7EuCHIT.js";const y=JSON.parse('{"title":"宿主组件与平台适配","description":"","frontmatter":{},"headers":[],"relativePath":"developers/components.md","filePath":"developers/components.md","lastUpdated":1795360698000}'),o={name:"developers/components.md"};function c(i,e,s,l,n,h){return d(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="宿主组件与平台适配" tabindex="-1">宿主组件与平台适配 <a class="header-anchor" href="#宿主组件与平台适配" aria-label="Permalink to &quot;宿主组件与平台适配&quot;">​</a></h1><p>此页按界面区域列出宿主现有的公开配置和扩展入口。参数类型、默认值和约束以<a href="/LyraPlayer-docs-site/config/reference/">配置参考</a>为准。</p><table tabindex="0"><thead><tr><th>组件或区域</th><th>配置表</th><th>公开行为或扩展</th></tr></thead><tbody><tr><td>外壳、抽屉和卡片布局</td><td><code>shell</code>、<code>geometry</code></td><td><a href="/LyraPlayer-docs-site/plugins/navigation">导航扩展</a></td></tr><tr><td>底部播放条</td><td><code>dock</code>、<code>theme</code></td><td><a href="/LyraPlayer-docs-site/plugins/playback">播放接口</a></td></tr><tr><td>播放页、封面和流动背景</td><td><code>player</code>、<code>cover_fx</code>、<code>flow</code></td><td><a href="/LyraPlayer-docs-site/plugins/styles">样式与绘制</a></td></tr><tr><td>歌词</td><td><code>player</code> 的 <code>lyric_*</code> 参数</td><td>歌词资源与播放进度由宿主管理</td></tr><tr><td>展开面板</td><td><code>sheet</code>、<code>scroll</code></td><td><a href="/LyraPlayer-docs-site/plugins/styles">Scene 绘制协议</a></td></tr><tr><td>资料库和搜索</td><td><code>search</code>、<code>profile</code>、<code>scroll</code></td><td><a href="/LyraPlayer-docs-site/plugins/media">媒体资源</a>、<a href="/LyraPlayer-docs-site/plugins/personal-library">私人资料库</a></td></tr><tr><td>设置页</td><td><code>settings</code>、<code>theme</code></td><td><a href="/LyraPlayer-docs-site/plugins/settings-page">声明式设置页协议</a></td></tr><tr><td>样式选择器</td><td><code>style</code></td><td>宿主提供 Bloom、Ember 和沉浸样式。插件可以向同一选择器提供样式描述</td></tr></tbody></table><h2 id="配置与应用样式" tabindex="-1">配置与应用样式 <a class="header-anchor" href="#配置与应用样式" aria-label="Permalink to &quot;配置与应用样式&quot;">​</a></h2><ul><li>改全局配色用 <code>theme</code>。改尺寸和间距用对应区域的表。配置读写遵循<a href="/LyraPlayer-docs-site/plugins/config-schema">配置接口和字段约束</a>。</li><li>播放页整体样式用<a href="/LyraPlayer-docs-site/plugins/styles">样式与绘制接口</a>。需要自绘时通过 Scene 提交画面。</li><li>声明式设置行由宿主绘制。插件接收激活或确认消息，并处理校验、持久化和失败反馈。行标记、禁用状态、当前值和可用操作见<a href="/LyraPlayer-docs-site/plugins/settings-page">设置页协议</a>。</li></ul><h2 id="播放控件、进度条和队列" tabindex="-1">播放控件、进度条和队列 <a class="header-anchor" href="#播放控件、进度条和队列" aria-label="Permalink to &quot;播放控件、进度条和队列&quot;">​</a></h2><p>播放按钮根据当前播放状态显示播放或暂停。上一首、下一首和进度拖动发出播放请求；宿主通过播放接口报告当前位置、时长及播放状态。替换这些控件时，用同一组公开状态更新按钮与进度条。<a href="/LyraPlayer-docs-site/plugins/playback">播放接口</a>、<a href="/LyraPlayer-docs-site/config/reference/ui-player">播放页配置</a>。</p><p>队列面板按当前队列顺序显示曲目，当前行跟随队列提供的活动位置。模式菜单使用稳定模式 ID，队列行号用于定位当前队列中的条目。<a href="/LyraPlayer-docs-site/plugins/rules">播放模式与队列</a>、<a href="/LyraPlayer-docs-site/config/reference/ui-sheet">队列面板配置</a>。</p><h2 id="资料库、收藏与收听记录" tabindex="-1">资料库、收藏与收听记录 <a class="header-anchor" href="#资料库、收藏与收听记录" aria-label="Permalink to &quot;资料库、收藏与收听记录&quot;">​</a></h2><p>资料库呈现媒体列表、分组和收藏。播放、添加和删除等操作通过公开能力执行。收藏或收听记录为空时，扩展可以用对应数据的空状态呈现。权限和媒体访问由宿主或当前 Android Activity 处理。<a href="/LyraPlayer-docs-site/plugins/media-actions">媒体操作</a>、<a href="/LyraPlayer-docs-site/plugins/personal-library">私人资料库</a>、<a href="/LyraPlayer-docs-site/plugins/listening-history">收听记录</a>。</p><h2 id="资料库分组标题与展开行" tabindex="-1">资料库分组标题与展开行 <a class="header-anchor" href="#资料库分组标题与展开行" aria-label="Permalink to &quot;资料库分组标题与展开行&quot;">​</a></h2><p>艺术家和专辑页按曲目信息分组。「我的」提供歌单、流派、文件夹和语言入口。分组标题显示名称、封面和数量。可折叠分组展开后显示曲目行，收起只隐藏这些行。替换资料库呈现时，可以保留宿主的曲目元数据和媒体操作，并独立管理分组的展开状态。<a href="/LyraPlayer-docs-site/config/classification">分类与文案配置</a>、<a href="/LyraPlayer-docs-site/plugins/media">媒体数据插件</a>、<a href="/LyraPlayer-docs-site/plugins/media-actions">媒体操作</a>。</p><p>曲目行封面尺寸使用 <code>player.cover_dp</code>。展开行缩进由宿主版本决定。SDK 配置快照列出 <code>player.group_indent_dp</code>。使用共享布局间距的宿主从 <code>layout.min_gap_dp</code> 取值，改变它也会影响其他使用共享间距的组件。调整缩进会减少展开行标题和副标题的可用宽度。写入前通过配置接口确认目标宿主包含该键。<a href="/LyraPlayer-docs-site/config/reference/ui-player">播放与列表配置</a>、<a href="/LyraPlayer-docs-site/plugins/config-schema">配置接口</a>。</p><h2 id="资料库滚动条、字母索引和横屏列" tabindex="-1">资料库滚动条、字母索引和横屏列 <a class="header-anchor" href="#资料库滚动条、字母索引和横屏列" aria-label="Permalink to &quot;资料库滚动条、字母索引和横屏列&quot;">​</a></h2><p>支持 <code>library</code> 配置表的宿主可通过 <code>library.rail_dp</code> 设置滚动条宽度，<code>library.rail_hit_dp</code> 设置触摸范围，<code>library.rail_min_dp</code> 设置最小滑块长度。触摸范围至少应等于可见宽度。字母索引字号使用 <code>library.index_sp</code>，单位为 sp。字母索引用于按字母排序的曲目列表，拖动滚动条时会标出当前位置对应的字母。</p><p>支持 <code>landscape.cell_dp</code> 的宿主用它计算资料库横屏列数。可用宽度达到多个单元宽度时可以显示多列，窄窗口至少保留一列。竖屏使用单列。完全自绘的资料库从帧布局取得可用区域，在自己的绘制与触摸处理中使用同一列布局。<a href="#像素、密度和字体缩放">像素、密度和字体缩放</a>、<a href="/LyraPlayer-docs-site/plugins/navigation">导航扩展</a>。</p><h2 id="外部媒体集合入口与曲目列表" tabindex="-1">外部媒体集合入口与曲目列表 <a class="header-anchor" href="#外部媒体集合入口与曲目列表" aria-label="Permalink to &quot;外部媒体集合入口与曲目列表&quot;">​</a></h2><p>实现集合目录能力的媒体提供者可以在资料库「我的」中提供集合入口。入口显示集合标题。打开入口后，宿主按集合 UID 请求内容，曲目列表显示该请求已发布的条目。离开集合时，宿主取消浏览请求。点击曲目后，播放队列保留自己的条目，退出集合仍可继续播放。<a href="/LyraPlayer-docs-site/plugins/collection-directory">集合目录</a>、<a href="/LyraPlayer-docs-site/plugins/media">媒体数据插件</a>。</p><h2 id="搜索框和结果行" tabindex="-1">搜索框和结果行 <a class="header-anchor" href="#搜索框和结果行" aria-label="Permalink to &quot;搜索框和结果行&quot;">​</a></h2><p><code>search.min_text_width_dp</code> 为搜索框文本和结果行文本设置统一的最小测量宽度，默认 40 dp，必须大于零。<code>search.field_text_reserve_dp</code> 为搜索框文本预留额外横向空间，默认 32 dp，可设为零。搜索面板的高度、搜索框外边距和结果行高度仍各自由对应的 <code>search</code> 字段控制。<a href="/LyraPlayer-docs-site/config/reference/ui-search">搜索配置</a>。</p><p>搜索结果可能来自本地曲库、媒体源或插件仓库。媒体结果展示曲目信息和封面，仓库结果展示插件名称、版本、大小和当前可用操作。仓库返回的行号只在当前版本有效，更新目录后需要重新查询再使用行号。若插件只提供媒体数据，默认搜索页仍可展示结果和封面。<a href="/LyraPlayer-docs-site/plugins/media">媒体资源</a>、<a href="/LyraPlayer-docs-site/reference/services">服务目录</a>。</p><h2 id="android-布局和能力" tabindex="-1">Android 布局和能力 <a class="header-anchor" href="#android-布局和能力" aria-label="Permalink to &quot;Android 布局和能力&quot;">​</a></h2><p>宿主从 Android 8（API 26）起支持，正式插件应提供 <code>arm64-v8a</code> 构建。插件使用公开帧和布局数据适配当前窗口尺寸及安全区。横屏、竖屏和有系统栏遮挡的窗口都应使用实际可用空间做绘制和命中。尺寸单位查对应配置键的定义，绘制坐标查 Scene 协议。</p><p>调用 Android 能力时，遵循<a href="/LyraPlayer-docs-site/plugins/android">Android 平台契约</a>的线程、引用和权限要求。能力可用性按运行设备版本及宿主声明判断。</p><h2 id="像素、密度和字体缩放" tabindex="-1">像素、密度和字体缩放 <a class="header-anchor" href="#像素、密度和字体缩放" aria-label="Permalink to &quot;像素、密度和字体缩放&quot;">​</a></h2><p>通过 <code>LYRA_INTERFACE_PRESENTATION_CONTEXT</code>（17）在帧线程读取 <code>LyraPresentationSnapshotV3</code>。调用 <code>snapshot</code> 前将 <code>size</code> 设为 <code>sizeof(snapshot)</code>，并检查返回值。整卡片样式的绘制回调优先使用本次回调收到的卡片矩形，选择器预览时这个矩形可能比主卡片小。</p><table tabindex="0"><thead><tr><th>输入</th><th>使用方式</th></tr></thead><tbody><tr><td><code>width</code>、<code>height</code> 与 <code>card</code>、<code>cover</code>、<code>library</code> 等矩形</td><td>使用当前窗口的像素坐标。自绘和触摸命中共用同一矩形</td></tr><tr><td>配置键定义为 dp</td><td>乘以当前 <code>density</code> 后用于像素布局</td></tr><tr><td>配置键定义为 sp</td><td>乘以当前 <code>density</code> 和 <code>font_scale</code> 后用于文字布局</td></tr><tr><td>安全区</td><td>宿主默认组件已处理自身布局。扩展叠加内容可以使用宿主提供的区域矩形。完全自绘的根若需要原始系统栏或挖孔内边距，可通过当前 Android Activity 查询系统能力</td></tr></tbody></table><p>窗口旋转、大小变化或系统字体缩放改变后，按新的帧数据计算绘制与命中。缓存文字布局时，把实际文字宽度和换算后的字号纳入缓存条件。Android 进程、线程和权限的约束适用于完全自绘的根和局部扩展。<a href="/LyraPlayer-docs-site/reference/abi">公开 SDK</a>、<a href="/LyraPlayer-docs-site/plugins/styles">样式与绘制</a>、<a href="/LyraPlayer-docs-site/plugins/android">Android 平台契约</a>。</p>',28)])])}const f=a(o,[["render",c]]);export{y as __pageData,f as default};
